<?php require __DIR__.'/config/bootstrap.php';$s=$pdo->query('SELECT * FROM courses WHERE is_active=1 ORDER BY created_at DESC');$courses=$s->fetchAll();$page_title='Courses';require __DIR__.'/includes/header.php';?>
<h1 class="text-3xl font-bold">Available courses</h1><p class="text-slate-600 mt-2">Choose a course to view its details and enroll.</p><div class="grid md:grid-cols-3 gap-5 mt-7"><?php foreach($courses as $c): ?><article class="bg-white border rounded-xl p-6 shadow-sm flex flex-col"><p class="text-xs text-blue-700 font-semibold uppercase"><?= e($c['duration']) ?></p><h2 class="text-xl font-bold mt-2"><?= e($c['title']) ?></h2><p class="text-slate-600 mt-3 flex-1"><?= e(mb_strimwidth($c['description'],0,130,'...')) ?></p><p class="text-sm mt-4">Instructor: <?= e($c['instructor']) ?></p><a class="mt-5 text-center bg-blue-700 text-white p-3 rounded-lg" href="<?= BASE_URL ?>/course.php?id=<?= (int)$c['id'] ?>">View course</a></article><?php endforeach; ?><?php if(!$courses): ?><p>No courses available yet.</p><?php endif; ?></div><?php require __DIR__.'/includes/footer.php';?>
